import React, {  useEffect, useRef, useState,useCallback, act, useContext } from 'react';
import { Button } from 'react-bootstrap';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from '../api/axios';
import { useStompClient, useSubscription } from 'react-stomp-hooks';
import user_icon from '../img/user_icon.png'
import { usernameContext } from '../Context';
import useWebSocket, { ReadyState } from "react-use-websocket"


const  Home = () => {

  const [socketUrl, setSocketUrl] = useState('ws://localhost:8080/ws');

//    const [messageHistory, setMessageHistory] =
//     useState < MessageEvent < string > [] > [];
  const { sendMessage, lastMessage, readyState } = useWebSocket(socketUrl);



